package reactor.netty.http.client; import io.netty.channel.ChannelOption; import java.net.SocketAddress; import java.time.Duration; import java.util.function.Supplier;
public class HttpClient {public Supplier<? extends SocketAddress> remote;public int connectTimeout;public Duration responseTimeout;public static HttpClient create(){return new HttpClient();}public <T> HttpClient option(ChannelOption<T> o,T v){if(v instanceof Integer i)connectTimeout=i;return this;}public HttpClient responseTimeout(Duration d){responseTimeout=d;return this;}public HttpClient remoteAddress(Supplier<? extends SocketAddress> s){remote=s;return this;}}
